import{_ as o,l as i,o as e,c as n,v as t,p as s,x as l,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"注意力头剪枝","description":"","frontmatter":{"title":"注意力头剪枝","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/attention-head-pruning.md","filePath":"llm/attention-head-pruning.md","lastUpdated":1789023840000}'),A={name:"llm/attention-head-pruning.md"};function E(_,a,c,m,u,B){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="注意力头剪枝" tabindex="-1">注意力头剪枝 <a class="header-anchor" href="#注意力头剪枝" aria-label="Permalink to &quot;注意力头剪枝&quot;">​</a></h1><div class="epigraph"><p>推理时关掉一部分头，翻译或编码往往几乎不掉；那是静态冗余，不是 Deja Vu 那种逐步预测。</p><footer>—— Michel, Levy, Neubig, Are Sixteen Heads Really Better than One?, NeurIPS 2019；Voita et al., ACL 2019</footer></div><p><a href="/llm/deja-vu-sparsity">上一课</a> 每步预测保留哪些头。<a href="/llm/attention-head-roles">头的功能分化</a> 已经给出静态故事：少数头干活，许多头平坦。本课动手：<strong>一次性删头</strong>，留下的模型仍是标准 MHA，只是头数变少。缺口是重要性怎么估、删完要不要愈合，以及它和 GQA 不是同一件事。后课离开稀疏，进入低秩分解。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Michel 等人在翻译模型上逐头置零，发现不少头对 BLEU 几乎无贡献，甚至一层只留一头仍能工作。Voita 等人用门控看到头的专门化与可剪性。LLM 上同样的实验更贵，但逻辑不变：多头提供槽位，槽位填不满。缺口是把「可剪」写成部署动作：删哪些、\\(d_h\\) 是否跟着变、KV 缓存是否按头数下降。</p><p>GQA 从设计上共享 K/V，是训练时的形状选择。剪头是训练后删已经学开的头。把剪完的 32 头模型叫「变成 GQA」是错的——GQA 的组结构与随机删头留下的不规则子集不同。</p><p><span class="marginnote">重要性不能只看注意力权重熵。平坦的头可能仍通过值向量做常偏置；应对输出做干预，与专精化分析课同一纪律。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>校准或验证集上，对每个头做置零（或缩放到 0），看损失 / 下游跌点，贪心删跌点最小的头，或按层保留固定个数。删完可选短微调或 <a href="/llm/lora">LoRA</a> 愈合；one-shot 在中等比例往往可接受，激进删头需要愈合。实现上从 \\(W_Q,W_K,W_V,W_O\\) 去掉对应列块，KV 缓存宽度下降，这是真加速，不依赖稀疏核。</p><p>与 2:4 / Wanda 叠：先定头数再对留下的投影做权重稀疏，校准必须在已剪头的图上做。</p>',10)),(e(),s(p,null,{default:l(()=>[h(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%90%84%E5%A4%B4%22%5D%20--%3E%20INTV%5B%22%E7%BD%AE%E9%9B%B6%E5%B9%B2%E9%A2%84%22%5D%0A%20%20INTV%20--%3E%20RANK%5B%22%E6%8C%89%E8%B7%8C%E7%82%B9%E6%8E%92%E5%BA%8F%22%5D%0A%20%20RANK%20--%3E%20DROP%5B%22%E5%88%A0%E9%99%A4%E4%BD%8E%E8%B4%A1%E7%8C%AE%E5%A4%B4%22%5D%0A%20%20DROP%20--%3E%20HEAL%5B%22%E5%8F%AF%E9%80%89%E7%9F%AD%E5%BE%AE%E8%B0%83%20%2F%20LoRA%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多头是并列子空间。冗余头的 \\(W_Q\\)/\\(W_K\\) 张成的方向与其它头高度相关，删掉后 SDPA 的加权和几乎不变。孤点头（归纳头、位置头）干预跌点大，对应 MoE 课的孤点专家，不可先删。层间不均：底层更偏位置、上层更偏内容，应按层配额而不是全局一个阈值，否则底层被删光。</p><p>Decode 收益主要来自 KV 字节与 QKV GEMM 变瘦，不是来自 SDPA 的 \\(n^2\\) 魔术——头数减半，SDPA FLOPs 大致减半，但长上下文仍平方。不要宣称剪头解决长上下文。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要按可视化「好看」删头。不要在 RL 后的推理模型上照搬预训练的头排名——<a href="/llm/grpo">GRPO</a> 会改写头的用法，须重测。激进剪头伤长链自检，比伤短 PPL 更早。下一课对留下的稠密矩阵做低秩分解，删除的是秩而不是头。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>头剪枝是静态结构化删除，KV 与 QKV 变瘦，有密核加速。</li><li>用干预跌点排序，不要用注意力图故事。</li><li>按层配额保护孤点头；与 GQA 设计不是同一形状。</li><li>RL / 指令后必须重测头重要性。</li><li>出处：Michel et al., NeurIPS 2019；Voita et al., ACL 2019。</li></ul>',7))])}const V=o(A,[["render",E]]);export{f as __pageData,V as default};
